before:
Complete local C example; the app itself does not execute it:
```c
#include <stdio.h>
#include <stdlib.h>

void release(int **owner) {
 free(*owner);
 *owner = NULL;
}
int main(void) {
 int *p = malloc(sizeof *p);
 if (p == NULL) { return 1; }
 release(&p);
 printf("%d\n", p == NULL);
}
```

